# Generated by build.py from recipe.yml for recipe gs-put-and-get-an-object. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'store/photos', 'readonly/photos', 'open/photos' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'note.txt'), "uploaded over gs`n")
[IO.File]::WriteAllText((Join-Path $PWD 'store/photos/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'readonly/photos/hello.txt'), "hello, read only`n")
[IO.File]::WriteAllText((Join-Path $PWD 'open/photos/hello.txt'), "hello to anyone`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:storage.googleapis.com,DNS:photos.s3.us-east-1.amazonaws.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'GOOGTESTKEY:s3cret', '--allow-uploads', 'gs://127.0.0.1:8080/', 's3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --cacert server.pem --connect-to ::127.0.0.1:8080 -u GOOGTESTKEY:s3cret -T note.txt gs://photos/note.txt gs://photos/note.txt } finally { Stop-Process $server0 }
